pub enum CradleDecision {
    Pass,
    Reject(CradleRejectReason),
}

pub fn evaluate(cfg: &CradleFilterConfig, candidate: &LaunchCandidate) -> CradleDecision {
    if candidate.pool_var_proxy_pct < cfg.min_pool_var_proxy_pct {
        return CradleDecision::Reject(CradleRejectReason::PoolVarTooLow);
    }
    if cfg.max_pool_var_proxy_pct > 0.0
        && candidate.pool_var_proxy_pct >= cfg.max_pool_var_proxy_pct
    {
        return CradleDecision::Reject(CradleRejectReason::PoolVarTooHigh);
    }
    if candidate.pair_age_sec > cfg.max_pair_age_sec {
        return CradleDecision::Reject(CradleRejectReason::PairTooOld);
    }
    if candidate.liquidity_usd < cfg.min_liquidity_usd {
        return CradleDecision::Reject(CradleRejectReason::LiquidityTooLow);
    }
    if candidate.market_cap_usd < cfg.min_market_cap_usd {
        return CradleDecision::Reject(CradleRejectReason::MarketCapTooLow);
    }
    if cfg.max_market_cap_usd > 0.0 && candidate.market_cap_usd > cfg.max_market_cap_usd {
        return CradleDecision::Reject(CradleRejectReason::MarketCapTooHigh);
    }
    if cfg.min_volume_24h_usd > 0.0 && candidate.volume_24h_usd < cfg.min_volume_24h_usd {
        return CradleDecision::Reject(CradleRejectReason::VolumeTooLow);
    }
    CradleDecision::Pass
}

